#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAXV 8

int main(int argc, char **argv) {
    if (argc < 2) return 0; // no test cases
    int pos = 1;
    int T = atoi(argv[pos++]);
    for (int tc = 0; tc < T; ++tc) {
        if (pos + 1 >= argc) { puts("INVALID_INPUT"); return 0; }
        int n = atoi(argv[pos++]);
        int m = atoi(argv[pos++]);
        if (n <= 0 || n > MAXV || m < 0 || m > n * (n - 1)) {
            puts("INVALID_INPUT");
            // skip remaining arguments for this test case if any
            pos += 2 * m;
            continue;
        }
        int indeg[MAXV] = {0};
        int adj[MAXV][MAXV] = {{0}}; // adjacency matrix for simplicity
        int valid = 1;
        for (int i = 0; i < m; ++i) {
            if (pos + 1 >= argc) { valid = 0; break; }
            int u = atoi(argv[pos++]);
            int v = atoi(argv[pos++]);
            if (u < 0 || u >= n || v < 0 || v >= n) { valid = 0; }
            else {
                if (!adj[u][v]) { // avoid duplicate edges affecting indegree
                    adj[u][v] = 1;
                    indeg[v]++;
                }
            }
        }
        if (!valid) {
            puts("INVALID_INPUT");
            continue;
        }
        // Kahn's algorithm
        int order[MAXV];
        int out_cnt = 0;
        int used[MAXV] = {0};
        while (out_cnt < n) {
            int found = -1;
            for (int v = 0; v < n; ++v) {
                if (!used[v] && indeg[v] == 0) { found = v; break; }
            }
            if (found == -1) break; // cycle
            used[found] = 1;
            order[out_cnt++] = found;
            for (int w = 0; w < n; ++w) {
                if (adj[found][w]) {
                    indeg[w]--;
                }
            }
        }
        if (out_cnt < n) {
            puts("CYCLE");
        } else {
            for (int i = 0; i < n; ++i) {
                if (i) putchar(' ');
                printf("%d", order[i]);
            }
            putchar('\n');
        }
    }
    return 0;
}
